import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.io.BufferedWriter;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.util.HashMap;
import java.util.Map;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        int BAD = 11111;
        int rows;
        int cols;
        Map<IntIntPair, Integer>[] mem;

        boolean contains(int memBits, int index) {
            if(index < 0) return false;
            return ((memBits >> index) & 1) == 1;
        }

        int add(int memBits, int index) {
            if(((memBits >> index) & 1) == 0) {
                memBits |= (1 << index);
            }
            return memBits;
        }

        int countBits(int memBits) {
            int res = 0;
            while(memBits > 0) {
                if((memBits & 1) == 1) res++;
                memBits >>= 1;
            }
            return res;
        }

        void runTests() {
            if(contains(5, 0) == false) throw new RuntimeException();
            if(contains(5, 1) == true) throw new RuntimeException();
            if(contains(5, -1) == true) throw new RuntimeException();
            if(contains(5, 2) == false) throw new RuntimeException();
            if(contains(5, 3) == true) throw new RuntimeException();
            if(add(0, 2) != 4) throw new RuntimeException();
            if(add(4, 0) != 5) throw new RuntimeException();
            if(add(5, 0) != 5) throw new RuntimeException();
            if(countBits(5) != 2) throw new RuntimeException();
        }

        int solveDP(int row, int remabove, int squareabove) {
            if(row == rows) {
                return (remabove == 0) ? 0 : BAD;
            }
            IntIntPair key = new IntIntPair(remabove, squareabove);
            if(mem[row].containsKey(key))
                return mem[row].get(key);
            int result = BAD;
            int totalConfigurations = 1 << cols;
            for(int configuration = 0; configuration < totalConfigurations; configuration++) {
                int have = 0;
                for(int j = 0; j < cols; j++) {
                    if(((configuration >> j) & 1) == 1) {
                        have |= (1 << j);
                    }
                }
                boolean valid = true;
                for(int above = 0; above < cols; above++) {
                    if(((remabove >> above) & 1) == 1) {
                        if(((have >> above) & 1) == 0) {
                            valid = false;
                            break;
                        }
                    }
                }
                if(valid) {
                    int nextRem = 0;
                    for(int j = 0; j < cols; j++) {
                        if(!contains(have, j - 1) && !contains(have, j) && !contains(have, j + 1) && !contains(squareabove, j)) {
                            nextRem |= (1 << j);
                        }
                    }
                    int candidate = countBits(have) + solveDP(row + 1, nextRem, have);
                    result = Math.min(result, candidate);
                }
            }
            mem[row].put(key, result);
            return result;
        }

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            runTests();
            int n = in.readInt(), m = in.readInt();
            cols = Math.min(n, m);
            rows = Math.max(n, m);
            mem = new HashMap[rows];
            for(int i = 0; i < rows; i++) mem[i] = new HashMap<>();
            int solution = solveDP(0, 0, 0);
            out.printLine(cols * rows - solution);
        }
    }

    static class IntIntPair {
        public final int first;
        public final int second;

        public IntIntPair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        public boolean equals(Object o) {
            if(this == o) return true;
            if(o == null || getClass() != o.getClass()) return false;
            IntIntPair pair = (IntIntPair) o;
            return first == pair.first && second == pair.second;
        }

        public int hashCode() {
            int result = Integer.hashCode(first);
            result = 31 * result + Integer.hashCode(second);
            return result;
        }

        public String toString() {
            return "(" + first + "," + second + ")";
        }

        public int compareTo(IntIntPair o) {
            int cmp = Integer.compare(first, o.first);
            if(cmp != 0) return cmp;
            return Integer.compare(second, o.second);
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if(numChars == -1) throw new InputMismatchException();
            if(curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch(IOException e) {
                    throw new InputMismatchException();
                }
                if(numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while(isSpaceChar(c)) c = read();
            int sign = 1;
            if(c == '-') {
                sign = -1;
                c = read();
            }
            int value = 0;
            do {
                if(c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = read();
            } while(!isSpaceChar(c));
            return value * sign;
        }

        public boolean isSpaceChar(int c) {
            if(filter != null) return filter.isSpaceChar(c);
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void close() {
            writer.close();
        }

        public void printLine(int value) {
            writer.println(value);
        }
    }
}
